lib='''from collections import deque

def components(grid, connectivity=8):
    """All connected components of nonzero cells; each as (top, left, bounding-box grid of 0/1)."""
    h, w = len(grid), len(grid[0])
    seen = set(); out = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] and (i, j) not in seen:
                q = deque([(i, j)]); seen.add((i, j)); cells = []
                while q:
                    y, x = q.popleft(); cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy and dx and connectivity == 4:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] and (ny, nx) not in seen:
                                seen.add((ny, nx)); q.append((ny, nx))
                ys = [c[0] for c in cells]; xs = [c[1] for c in cells]
                out.append((min(ys), min(xs),
                            [[1 if (y, x) in cells else 0 for x in range(min(xs), max(xs) + 1)]
                             for y in range(min(ys), max(ys) + 1)]))
    return out

def is_symmetric(g):
    """True if the square-or-rect grid has any symmetry: horizontal, vertical, or (square only) diagonal."""
    n, m = len(g), len(g[0])
    if all(r == r[::-1] for r in g): return True
    if g == g[::-1]: return True
    if n == m and all(g[i][j] == g[j][i] for i in range(n) for j in range(n)): return True
    if n == m and all(g[i][j] == g[n - 1 - j][n - 1 - i] for i in range(n) for j in range(n)): return True
    return False

def odd_shape_out(grid, connectivity=8):
    """The bounding-box grid of the single component with no symmetry (the odd one out)."""
    odd = [g for _, _, g in components(grid, connectivity) if not is_symmetric(g)]
    return odd[0]
'''
